function drillBlogger(handle) {
  if (!selectBloggerHandle(handle)) return; // 双保险：委托处已校验，这里再校验一次
  switchMode('blogger');
}

// ==========================================
// B2-b：每小时新增列 + 值得跟/不值得 + #tweet= 深链
// 这一段里的外部数据全部用 textContent / 属性赋值写入，不做 HTML 字符串拼接。
// ==========================================
const MONITOR_URL = '/api/radar/monitor';
const FEEDBACK_URL = '/api/radar/feedback';
const MONITOR_HINT = {
  missing: '监控未运行',
  stale: '数据已过期',
  invalid: '监控数据异常'
};
const HIT_LABEL = {
  lowfan_burst: '低粉大爆款',
  new_fast: '新帖起飞',
  hourly_delta: '小时增量',
  upgrade_100k: '破10万'
};
const VERDICT_LABEL = { worth: '值得跟', not_worth: '不值得' };

let monitorState = { status: 'missing', generated_at: null, run_id: null, tweets: {}, feedback: {} };

function monitorHourlyText(status) {
  if (status === 'missing') return MONITOR_HINT.missing;
  if (status === 'stale') {
    const hours = Math.max(0, Math.floor((Date.now() - (parseStampMs(monitorState.generated_at) || Date.now())) / 3600000));
    return MONITOR_HINT.stale + '（' + hours + ' 小时前）';
  }
  if (status === 'invalid') return MONITOR_HINT.invalid;
  return '';
}

function formatHourly(value) {
  if (value === null || value === undefined) return '—';
  const number = safeNum(value);
  if (number === null || number < 0) return '—';
  const sign = '+';
  if (number >= 10000) return sign + (number / 10000).toFixed(1) + '万/h';
  if (number >= 1000) return sign + (number / 1000).toFixed(1) + 'k/h';
  return sign + Math.round(number) + '/h';
}

function hourlyCellText(tweetId) {
  const hint = monitorState.status === 'ok' ? '' : monitorHourlyText(monitorState.status);
  if (hint) return { text: hint, hint: true, hit: null };
  const record = tweetId ? monitorState.tweets[tweetId] : null;
  if (!record || record.is_stale) return { text: '—', hint: false, hit: null };
  return { text: formatHourly(record.hourly_delta), hint: false,
           hit: (record.hit && HIT_LABEL[record.hit]) ? HIT_LABEL[record.hit] : null };
}

function monitorRow(tweetId) {
  const row = document.createElement('div');
  row.className = 'tweet-monitor-row';
  row.dataset.tweetId = tweetId;
  const label = document.createElement('span');
  label.className = 'tweet-monitor-label';
  label.textContent = '每小时新增';
  const value = document.createElement('span');
  value.className = 'tweet-monitor-value';
  row.appendChild(label);
  row.appendChild(value);
  row.appendChild(buildVerdictButtons(tweetId));
  updateMonitorRow(row, tweetId);
  return row;
}

// 就地更新文本，保留按钮节点不动
function updateMonitorRow(row, tweetId) {
  const view = hourlyCellText(tweetId);
  const value = row.querySelector('.tweet-monitor-value');
  if (value) {
    value.textContent = view.text;
    value.classList.toggle('is-hint', view.hint);
  }
  const existing = row.querySelector('.tweet-monitor-hit');
  if (view.hit && !existing) {
    const badge = document.createElement('span');
    badge.className = 'tweet-monitor-hit';
    badge.textContent = view.hit;
    row.insertBefore(badge, row.querySelector('.verdict-group'));
  } else if (view.hit && existing) {
    existing.textContent = view.hit;
  } else if (!view.hit && existing) {
    existing.remove();
  }
  return row;
}

function buildVerdictButtons(tweetId) {
  const group = document.createElement('span');
  group.className = 'verdict-group';
  if (!tweetId) return group;
  const current = monitorState.feedback[tweetId] ? monitorState.feedback[tweetId].verdict : null;
  ['worth', 'not_worth'].forEach((verdict) => {
    const button = document.createElement('button');
    button.type = 'button';
    button.className = 'verdict-btn verdict-' + verdict;
    button.dataset.verdict = verdict;
    button.dataset.tweetId = tweetId;
    button.textContent = VERDICT_LABEL[verdict];
    if (current === verdict) {
      button.classList.add('active');
      button.setAttribute('aria-pressed', 'true');
    } else {
      button.setAttribute('aria-pressed', 'false');
    }
    group.appendChild(button);
  });
  return group;
}

// 所有帖子卡片复用同一监控行与反馈队列；只追加一次。
function applyMonitorColumn(container) {
  if (!container) return;
  const cards = container.querySelectorAll('.vip-tweet-card, .tweet-card, .embedded-tweet-card');
  cards.forEach((card) => {
    const tweetId = safeText(card.getAttribute('data-tweet-id'));
    const anchor = card.querySelector('.vip-metrics-bar, .tweet-metrics-bar');
    if (!anchor || !tweetId) return;
    const isVip = card.classList.contains('vip-tweet-card');
    let row = card.querySelector('.tweet-monitor-row');
    if (row) { if (isVip) updateMonitorRow(row, tweetId); return; }
    if (isVip) row = monitorRow(tweetId);
    else {
      // Hourly columns belong to the VIP list; every other post still gets
      // the same feedback controls, keyed by the same exact string ID.
      row = document.createElement('div');
      row.className = 'tweet-monitor-row tweet-feedback-row';
      row.dataset.tweetId = tweetId;
      row.appendChild(buildVerdictButtons(tweetId));
    }
    anchor.parentNode.insertBefore(row, anchor.nextSibling);
  });
}

function refreshVerdictButtons() {
  const buttons = document.querySelectorAll('.verdict-btn');
  buttons.forEach((button) => {
    const tweetId = safeText(button.dataset.tweetId);
    const record = monitorState.feedback[tweetId];
    const active = !!record && record.verdict === button.dataset.verdict;
    button.classList.toggle('active', active);
    button.setAttribute('aria-pressed', active ? 'true' : 'false');
  });
}

function showMonitorToast(message, isError, titleText) {
  const container = document.getElementById('radar-toast-container');
  if (!container) return;
  const toast = document.createElement('div');
  toast.className = 'radar-toast ' + (isError ? 'warning' : 'success');
  const title = document.createElement('div');
  title.style.fontWeight = '700';
  title.style.marginBottom = '2px';
  title.textContent = titleText || (isError ? '保存失败' : '已保存');
  const body = document.createElement('div');
  body.style.fontSize = '12.5px';
  body.style.opacity = '0.95';
  body.textContent = message;
  toast.appendChild(title);
  toast.appendChild(body);
  container.appendChild(toast);
  setTimeout(() => { toast.remove(); }, isError ? 5000 : 3500);
}

async function postVerdict(tweetId, verdict) {
  const response = await fetch(FEEDBACK_URL, {
    method: 'POST',
    cache: 'no-store',
    headers: { 'Content-Type': 'application/json', 'X-Article-Studio': '1' },
    body: JSON.stringify({ tweet_id: tweetId, verdict: verdict })
  });
  if (!response.ok) {
    let reason = 'HTTP ' + response.status;
    try {
      const data = await response.json();
      if (data && typeof data.error === 'string') reason = data.error;
    } catch (e) { /* 非 JSON 错误体，保留状态码文案 */ }
    throw new Error(reason);
  }
  return response.json().catch(() => ({}));
}

// One ordering domain for GET snapshots and POST confirmations. Server versions
// order actual snapshots (including deletions); local order is the fallback for
// an older API and for responses spanning a server restart. Neither is a clock.
const verdictQueues = new Map();
let feedbackOrder = 0;
let feedbackReadFence = { revision: null, order: 0 };
let monitorAppliedOrder = 0;

function parseFeedbackRevision(value) {
  const match = typeof value === 'string' && value.match(/^([a-f0-9]{32}):([0-9]+)$/);
  return match ? { epoch: match[1], version: BigInt(match[2]) } : null;
}

function canApplyFeedback(state, revision, order) {
  if (revision && state.revision && revision.epoch === state.revision.epoch &&
      revision.version !== state.revision.version) {
    return revision.version > state.revision.version;
  }
  return order >= state.appliedOrder;
}

function confirmedVerdict(tweetId) {
  const record = monitorState.feedback[tweetId];
  return record && (record.verdict === 'worth' || record.verdict === 'not_worth') ? record.verdict : null;
}

function setVerdictBusy(tweetId, busy) {
  document.querySelectorAll('.verdict-btn[data-tweet-id="' + tweetId + '"]').forEach((node) => {
    if (busy) node.dataset.busy = '1';
    else delete node.dataset.busy;
  });
}

function verdictState(tweetId) {
  let state = verdictQueues.get(tweetId);
  if (!state) {
    const confirmed = confirmedVerdict(tweetId);
    state = { desired: confirmed, confirmed: confirmed, inFlight: false,
      seq: 0, appliedSeq: 0, intentSeq: 0,
      revision: feedbackReadFence.revision, appliedOrder: feedbackReadFence.order };
    verdictQueues.set(tweetId, state);
  }
  return state;
}

function applyConfirmedFeedback(tweetId, record, revision, order) {
  const state = verdictState(tweetId);
  if (!canApplyFeedback(state, revision, order)) return false;
  const verdict = record && (record.verdict === 'worth' || record.verdict === 'not_worth') ? record.verdict : null;
  if (verdict === null) delete monitorState.feedback[tweetId];
  else monitorState.feedback[tweetId] = record;
  state.confirmed = verdict;
  state.revision = revision;
  state.appliedOrder = Math.max(state.appliedOrder, order);
  return true;
}

function syncVerdictQueuesFromServer(records, rawRevision, order) {
  const revision = parseFeedbackRevision(rawRevision);
  const ids = new Set([...Object.keys(monitorState.feedback), ...Object.keys(records), ...verdictQueues.keys()]);
  ids.forEach((tweetId) => {
    const state = verdictState(tweetId);
    if (applyConfirmedFeedback(tweetId, records[tweetId], revision, order) && !state.inFlight) {
      state.desired = state.confirmed;
    }
  });
  // Remember an empty snapshot too, so a late read cannot resurrect a deletion
  // for a tweet that did not yet have a local queue.
  if (canApplyFeedback({ revision: feedbackReadFence.revision, appliedOrder: feedbackReadFence.order }, revision, order)) {
    feedbackReadFence = { revision: revision, order: order };
  }
}

function queueVerdict(tweetId, verdict) {
  const state = verdictState(tweetId);
  state.desired = state.desired === verdict ? null : verdict;
  state.intentSeq++;
  pumpVerdict(tweetId);
}

function pumpVerdict(tweetId) {
  const state = verdictState(tweetId);
  if (state.inFlight) return;
  if (state.desired === state.confirmed) { setVerdictBusy(tweetId, false); return; }
  state.inFlight = true;
  setVerdictBusy(tweetId, true);
  const seq = ++state.seq;
  const order = ++feedbackOrder;
  const target = state.desired;
  const intent = state.intentSeq;
  postVerdict(tweetId, target).then((record) => {
    const stored = record && typeof record === 'object' && 'verdict' in record ? record.verdict : target;
    const revision = parseFeedbackRevision(record && record.feedback_revision);
    const applied = applyConfirmedFeedback(tweetId, { ...record, verdict: stored }, revision, order);
    if (applied) state.appliedSeq = seq;
    // A later GET may have superseded this operation. Do not replay its old
    // intent as a new write; a genuinely newer click remains queued instead.
    if (state.intentSeq === intent) state.desired = state.confirmed;
    refreshVerdictButtons();
    if (applied) showMonitorToast(target === null ? '已撤销这条反馈' : ('已标记为「' + VERDICT_LABEL[target] + '」'), false);
  }).catch((error) => {
    if (state.intentSeq === intent) state.desired = state.confirmed;
    refreshVerdictButtons();
    showMonitorToast('保存失败：' + (error && error.message ? error.message : '未知错误'), true);
  }).then(() => {
    state.inFlight = false;
    setVerdictBusy(tweetId, state.desired !== state.confirmed);
    pumpVerdict(tweetId);
  });
}

function onVerdictClick(event) {
  const button = event.target instanceof Element ? event.target.closest('.verdict-btn') : null;
  if (!button) return;
  const tweetId = safeText(button.dataset.tweetId);
  const verdict = safeText(button.dataset.verdict);
  if (!tweetId || (verdict !== 'worth' && verdict !== 'not_worth')) return;
  queueVerdict(tweetId, verdict);
}

async function fetchMonitorView() {
  const order = ++feedbackOrder;
  try {
    const response = await fetch(MONITOR_URL, { cache: 'no-store' });
    if (!response.ok) throw new Error('HTTP ' + response.status);
    const data = await response.json();
    if (order >= monitorAppliedOrder) {
      monitorAppliedOrder = order;
      const status = ['ok', 'missing', 'stale', 'invalid'].indexOf(data && data.status) >= 0 ? data.status : 'invalid';
      monitorState = {
        status: status,
        generated_at: safeText(data && data.generated_at) || null,
        run_id: safeText(data && data.run_id) || null,
        tweets: isObject(data && data.tweets) ? data.tweets : {},
        feedback: monitorState.feedback
      };
    }
    syncVerdictQueuesFromServer(isObject(data && data.feedback) ? data.feedback : {}, data && data.feedback_revision, order);
    refreshVerdictButtons();
  } catch (error) {
    if (order >= monitorAppliedOrder) {
      monitorAppliedOrder = order;
      monitorState = { status: 'invalid', generated_at: null, run_id: null, tweets: {}, feedback: monitorState.feedback };
    }
  }
  applyMonitorColumn(document.getElementById('vip-tweets-feed'));
  return monitorState;
}

function hashTweetId() {
  const hash = safeText(window.location.hash || '');
  const match = hash.match(/^#tweet=([0-9]{1,25})$/);   // 只认完整匹配的 ASCII 数字，尾换行/编码串一律忽略
  return match ? match[1] : null;
}

let tweetFocusTimer = null;

function focusTweetFromHash() {
  clearTimeout(tweetFocusTimer);
  document.querySelectorAll('.tweet-focus').forEach((node) => node.classList.remove('tweet-focus'));
  const tweetId = hashTweetId();
  if (!tweetId) return false;
  const cards = document.querySelectorAll('[data-tweet-id="' + tweetId + '"]');
  const card = [...cards].find((node) =>
    node.matches('.vip-tweet-card, .tweet-card, .embedded-tweet-card') &&
    node.getClientRects().length > 0 && getComputedStyle(node).visibility === 'visible');
  if (!card) return false;
  card.scrollIntoView({ behavior: 'smooth', block: 'center' });
  card.classList.add('tweet-focus');
  tweetFocusTimer = setTimeout(() => card.classList.remove('tweet-focus'), 4000);
  return true;
}

function syncDeepLinkFilter(selector, key, value) {
  document.querySelectorAll(selector).forEach((button) => {
    button.classList.toggle('active', button.dataset[key] === value);
  });
}

function ensureDeepLinkTarget() {
  if (focusTweetFromHash()) return true;
  const tweetId = hashTweetId();
  if (!tweetId) return false;
  const vip = (Array.isArray(DATA_BUNDLE.vip_tweets) ? DATA_BUNDLE.vip_tweets : [])
    .find((tweet) => tweetIdOf(tweet) === tweetId && withinWindow(tweet, WINDOW_48H) && isViralTweet(tweet));
  const feed = (Array.isArray(DATA_BUNDLE.tweets) ? DATA_BUNDLE.tweets : [])
    .filter((tweet) => numOr(tweet && tweet.fc, 0) <= LOWFAN_MAX_FC && withinWindow(tweet, WINDOW_48H))
    .sort(cmpAgeAsc);
  const feedIndex = feed.findIndex((tweet) => tweetIdOf(tweet) === tweetId);
  const blogger = [...(Array.isArray(DATA_BUNDLE.vip_tweets) ? DATA_BUNDLE.vip_tweets : []),
    ...(Array.isArray(DATA_BUNDLE.tweets) ? DATA_BUNDLE.tweets : [])]
    .find((tweet) => tweetIdOf(tweet) === tweetId && withinWindow(tweet, WINDOW_48H) && isValidHandle(tweet.user));
  const cluster = (Array.isArray(DATA_BUNDLE.topic_clusters) ? DATA_BUNDLE.topic_clusters : [])
    .some((topic) => Array.isArray(topic && topic.embedded_tweets) && topic.embedded_tweets
      .some((tweet) => tweetIdOf(tweet) === tweetId && withinWindow(tweet, WINDOW_48H)));
  if (vip || feedIndex >= 0 || blogger || cluster) {
    currentTrack = 'all';
    syncDeepLinkFilter('.track-pill', 'track', currentTrack);
    if (vip) {
      currentVipUser = 'all';
      currentVipTime = withinWindow(vip, WINDOW_24H) ? 'today' : 'all_48h';
      currentVipTier = 'all';
      currentVipSort = 'time';
      currentVipSearch = '';
      const input = document.getElementById('vip-search-input');
      if (input) input.value = '';
      syncDeepLinkFilter('.vip-time-btn', 'time', currentVipTime);
      syncDeepLinkFilter('.vip-tier-btn', 'tier', currentVipTier);
      syncDeepLinkFilter('.vip-sort-btn', 'sort', currentVipSort);
      switchMode('vip');
    } else if (feedIndex >= 0) {
      currentTime = '48h';
      currentTier = 'all';
      currentSort = 'time';
      currentSearch = '';
      currentPage = Math.floor(feedIndex / PAGE_SIZE) + 1;
      const input = document.getElementById('search-input');
      if (input) input.value = '';
      syncDeepLinkFilter('.time-btn', 'time', currentTime);
      syncDeepLinkFilter('.filter-btn', 'tier', currentTier);
      syncDeepLinkFilter('.sort-btn', 'sort', currentSort);
      switchMode('feed');
    } else if (blogger) {
      selectBloggerHandle(blogger.user);
      switchMode('blogger');
    } else {
      switchMode('clusters');
    }
    if (focusTweetFromHash()) return true;
  }
  showMonitorToast('该帖不在当前雷达数据中', true, '未找到该帖');
  return false;
}

// ==========================================
// M4：读取本地 JSON 快照（不触发任何采集）
// ==========================================
// 核心列表字段：缺任何一个都不接受整包，绝不与内嵌旧数组混合成“新 run 成功”
const REQUIRED_LIST_FIELDS = ['tweets', 'vip_tweets', 'vip_bloggers', 'topic_clusters'];

function validateBundleShape(data) {
  if (!isObject(data)) return '数据不完整：响应不是 JSON 对象';
  const missing = [];
  const wrongType = [];
  REQUIRED_LIST_FIELDS.forEach(field => {
    const v = data[field];
    if (v === null || v === undefined) missing.push(field);
    else if (!Array.isArray(v)) wrongType.push(field);
  });
  if (missing.length > 0) {
    return '数据不完整：JSON 缺少必需列表字段 ' + missing.join('、') +
      '（本次读取整体作废，继续使用上一份可用数据，不与新 run 混合）';
  }
  if (wrongType.length > 0) {
    return '数据不完整：字段 ' + wrongType.join('、') + ' 类型错误（应为数组），本次读取整体作废';
  }
  return null;
}

// 先整体校验、再整体替换：不做「部分数组合并」
function applyBundle(bundle) {
  const shapeError = validateBundleShape(bundle);
  if (shapeError) throw new Error(shapeError);
  DATA_BUNDLE.tweets = bundle.tweets;
  DATA_BUNDLE.vip_tweets = bundle.vip_tweets;
  DATA_BUNDLE.vip_bloggers = bundle.vip_bloggers;
  DATA_BUNDLE.topic_clusters = bundle.topic_clusters;
  if (Array.isArray(bundle.key_bloggers)) DATA_BUNDLE.key_bloggers = bundle.key_bloggers;
  if (Array.isArray(bundle.vip_authors)) DATA_BUNDLE.vip_authors = bundle.vip_authors;
  if (isObject(bundle.all_followings_index)) DATA_BUNDLE.all_followings_index = bundle.all_followings_index;
  // 零值保留：0 也要写进去，不能被 || 吃掉
  DATA_BUNDLE.updated_at = safeText(bundle.updated_at).trim() || DATA_BUNDLE.updated_at;
  DATA_BUNDLE.today_virals = bundle.today_virals !== undefined ? bundle.today_virals : null;
  DATA_BUNDLE.h48_virals = bundle.h48_virals !== undefined ? bundle.h48_virals : null;
  DATA_BUNDLE.run_id = safeText(bundle.run_id).trim() || null;
  DATA_BUNDLE.coverage = isObject(bundle.coverage) ? bundle.coverage : null;
}

async function readBundleJson() {
  let res;
  try {
    res = await fetch(BUNDLE_URL + '?_t=' + Date.now(), { cache: 'no-store' });
  } catch (e) {
    throw new Error('网络请求失败：' + (e && e.message ? e.message : '无法连接'));
  }
  if (!res.ok) {
    throw new Error('HTTP ' + res.status + '（服务器返回失败状态）');
  }
  let data;
  try {
    data = await res.json();
  } catch (e) {
    throw new Error('JSON 解析失败：' + (e && e.message ? e.message : '响应不是合法 JSON'));
  }
  const shapeError = validateBundleShape(data);
  if (shapeError) throw new Error(shapeError);
  return data;
}

async function refreshFromDisk() {
  const btn = document.getElementById('btn-refresh-radar');
  if (btn) {
    btn.disabled = true;
    btn.textContent = '🔄 正在读取本地 JSON…';
    btn.removeAttribute('title');
  }
  showRadarToast('正在读取服务器上已保存的采集快照（本地 JSON，不触发新的全网采集）', 'info', 2500);
  try {
    const bundle = await readBundleJson();
    applyBundle(bundle);
    DATA_SOURCE = { kind: 'json', loadedAt: Date.now(), error: null };
    rerenderCurrentView();
    await fetchMonitorView();          // bundle 与监控接口同时读；后者失败不影响前者
    await ensureDeepLinkTarget();
    showRadarToast('读取完成：' + bundleSummaryLine(), 'success', 5200);
    if (btn) {
      btn.textContent = '✅ 已读取本地快照（不触发采集）';
      btn.title = '已读取 ' + formatBeijingTime(DATA_BUNDLE.updated_at) + ' 的快照';
    }
  } catch (err) {
    const reason = err && err.message ? err.message : '未知错误';
    DATA_SOURCE = { kind: DATA_SOURCE.kind, loadedAt: DATA_SOURCE.loadedAt, error: reason };
    rerenderCurrentView();
    console.warn('读取 radar bundle 失败：', reason);
    await ensureDeepLinkTarget();                     // bundle 读失败也给出「不在当前雷达数据中」
    showRadarToast('读取失败：' + reason, 'warning', 6500);
    if (btn) {
      btn.textContent = REFRESH_BTN_TEXT; // 绝不显示「已是最新」
      btn.title = '读取失败：' + reason;
    }
  } finally {
    if (btn) {
      setTimeout(() => {
        btn.disabled = false;
        if (btn.textContent.indexOf('正在读取') === 0) btn.textContent = REFRESH_BTN_TEXT;
      }, 400);
    }
  }
}

function showRadarToast(message, type, duration) {
  const container = document.getElementById('radar-toast-container');
  if (!container) return;
  const toast = document.createElement('div');
  toast.className = 'radar-toast ' + type;
  const icon = type === 'success' ? '✅' : (type === 'warning' ? '⚠️' : '🔄');
  const title = type === 'success' ? '已读取本地采集快照' : (type === 'warning' ? '读取失败' : '读取中');
  toast.innerHTML = '<div style="font-size:18px; line-height:1;">' + icon + '</div>' +
    '<div><div style="font-weight:700; margin-bottom:2px;">' + escapeHtml(title) + '</div>' +
    '<div style="font-size:12.5px; opacity:0.95;">' + escapeHtml(safeText(message)) + '</div></div>';
  container.appendChild(toast);
  setTimeout(() => {
    toast.style.opacity = '0';
    toast.style.transform = 'translateX(100%)';
    setTimeout(() => toast.remove(), 300);
  }, duration || 4000);
}

// ==========================================
// 事件绑定
// ==========================================
document.addEventListener('DOMContentLoaded', () => {
  // 视图切换
  const tabMap = { 'tab-clusters-btn': 'clusters', 'tab-vip-btn': 'vip', 'tab-feed-btn': 'feed', 'tab-blogger-btn': 'blogger' };
  Object.keys(tabMap).forEach(id => {
    const el = document.getElementById(id);
    if (el) el.addEventListener('click', () => switchMode(tabMap[id]));
  });
  document.getElementById('shortcut-to-vip-btn')?.addEventListener('click', () => switchMode('vip'));

  document.querySelectorAll('.track-pill').forEach(btn => {
    btn.onclick = () => setTrack(btn.dataset.track);
  });
  document.querySelectorAll('.vip-chip[data-user]').forEach(btn => {
    btn.onclick = () => {
      const user = safeText(btn.dataset.user);
      if (user !== 'all' && !isValidHandle(user)) return;
      document.querySelectorAll('.vip-chip').forEach(b => b.classList.remove('active'));
      btn.classList.add('active');
      currentVipUser = user;
      renderVipTweets();
    };
  });
  bindGroup('.vip-time-btn', 'time', v => { currentVipTime = v; });
  bindGroup('.vip-tier-btn', 'tier', v => { currentVipTier = v; });
  bindGroup('.vip-sort-btn', 'sort', v => { currentVipSort = v; });
  bindGroup('.time-btn', 'time', v => { currentTime = v; currentPage = 1; });
  bindGroup('.filter-btn', 'tier', v => { currentTier = v; currentPage = 1; });
  bindGroup('.sort-btn', 'sort', v => { currentSort = v; currentPage = 1; });

  function bindGroup(selector, key, setter) {
    document.querySelectorAll(selector).forEach(btn => {
      btn.onclick = () => {
        document.querySelectorAll(selector).forEach(b => b.classList.remove('active'));
        btn.classList.add('active');
        setter(btn.dataset[key]);
        if (currentMode === 'vip') renderVipTweets();
        else if (currentMode === 'feed') renderTweetsFeed();
      };
    });
  }

  const vipSearchInput = document.getElementById('vip-search-input');
  if (vipSearchInput) {
    vipSearchInput.addEventListener('input', (e) => {
      currentVipSearch = safeText(e.target.value).trim();
      renderVipTweets();
    });
  }
  const searchInput = document.getElementById('search-input');
  if (searchInput) {
    searchInput.addEventListener('input', (e) => {
      currentSearch = safeText(e.target.value).trim();
      currentPage = 1;
      renderTweetsFeed();
    });
  }
  const bloggerSearchInput = document.getElementById('blogger-search-input');
  if (bloggerSearchInput) {
    bloggerSearchInput.addEventListener('input', (e) => { bloggerSearchInput.dataset.touched = '1'; });
  }

  // 事件委托：数据只进 data-* 属性，绝不拼 inline handler
  document.addEventListener('click', (e) => {
    const target = e.target instanceof Element ? e.target : null;
    if (!target || typeof target.closest !== 'function') return;
    const drill = target.closest('[data-drill-handle]');
    if (drill) {
      const handle = safeText(drill.getAttribute('data-drill-handle'));
      if (!isValidHandle(handle)) return;
      drillBlogger(handle);
      return;
    }
    const action = target.closest('[data-action="vip-48h"]');
    if (action) {
      switchToVip48h();
      return;
    }
    const chip = target.closest('.blogger-chip[data-handle]');
    if (chip) {
      const handle = safeText(chip.getAttribute('data-handle'));
      if (!selectBloggerHandle(handle)) return;
      renderBloggerDossier(selectedBloggerHandle);
    }
  });

  document.getElementById('btn-refresh-radar')?.addEventListener('click', () => { refreshFromDisk(); });

  // 「值得跟 / 不值得」按钮：事件委托
  document.addEventListener('click', (event) => { onVerdictClick(event); });
  window.addEventListener('hashchange', () => { ensureDeepLinkTarget(); });   // 换 hash 同样自动定位

  // 每分钟重算时间窗（只重画，不读文件）
  setInterval(rerenderCurrentView, 60000);

  // 首屏：先用内嵌数据画出画面，再读服务器 JSON。
  // 这三处在用户切到对应视图之前也必须先刷新一次，避免残留 HTML 里的静态战绩或上一包的计数。
  renderStaticCounts();
  renderTopicClusters();
  renderDataStatus();
  focusTweetFromHash();
  fetchMonitorView();
  refreshBloggerChipArea();
  refreshVipChipArea();
  refreshFeedWindowCounts();
  refreshFromDisk();
});